def localDefect (T : C(K, E) →L[𝕜] C(K, E))
    (A : K → E →L[𝕜] E) (O : Set K) (t : K) : ℝ :=
  sSup {r : ℝ | ∃ f : C(K, E), ‖f‖ ≤ 1 ∧ VanishesOff O f ∧
    r = ‖T f t - A t (f t)‖}

